        db.query("cpu", 1000, 1040); // exactly block 0
        assertEquals(1, db.blocksDecoded());
        db.resetDecodeCount();
        db.query("cpu", 1025, 1045); // straddles blocks 0 (max 1030) and 1 (min 1040)
        assertEquals(2, db.blocksDecoded());
